def transform_correct(grid):
    """Replace background cells between two special cells of same color."""
    from collections import Counter
    all_cells = [c for row in grid for c in row]
    counter = Counter(all_cells)
    background = counter.most_common(1)[0][0]
    # Get non-background colors (specials)
    specials = [c for c in counter.keys() if c != background]
    print(f"Background: {background}, Specials: {specials}")

    result = [row[:] for row in grid]

    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == background:
                # Check horizontal
                if 0 < j < len(grid[i]) - 1:
                    left = grid[i][j-1]
                    right = grid[i][j+1]
                    if left in specials and right in specials:
                        result[i][j] = 2
                # Check vertical - need to bound check
                if 0 < i < len(grid) - 1:
                    up = grid[i-1][j]
                    down = grid[i+1][j]
                    if up in specials and down in specials:
                        result[i][j] = 2
    return result

